// Notes:
//   Original-mod unlock for LOOSE files. DREAM's music (.ogg in Documents/Sound), cinematics (.mp4 and the Daedra
//   .FLC in Documents/Movies) and extras (SpellIcons, Presets) are not .dfmod files, so the ModManager gate never
//   sees them. KnownOursLoose (generated by tools/known_ours_loose.py from our three DREAM loose-file zips) lists
//   each of them by leaf name + exact size. A loose file that matches a row while that row's key has no receipt is
//   treated as ABSENT by every loose-file lookup (MobileContentPath.Override / UserFiles / Exists, FLCPlayer,
//   Dynamic Music playlists), so the game uses its vanilla content instead. Anything else - the player's own music,
//   other loose mods, the same name at another size - is untouched.
//
//   Same lock-mode rules as the .dfmod gate: release builds enforce; test-app builds (IsTestBuild) only when
//   Documents/Mods/GameData/enforce-original-lock exists (ApplyLockMode / LockEnforced). Never throws; one log line
//   per key and decision. Cost: one dictionary lookup per resolved user file; a stat only on a name hit; the
//   receipt file is read once and re-read only after a ModManager scan (which may have added a receipt).
//   Spec: docs/superpowers/specs/2026-10-14-original-mod-unlock-design.md, "Loose files".

using System;
using System.Collections.Generic;
using System.IO;

namespace DaggerfallWorkshop.Game.Mobile
{
    public static partial class MobileOriginalMods
    {
        /// <summary>One loose file we ship for a Non-MIT mod (leaf name lower-case, exact size, unlock key).</summary>
        public struct LooseFile
        {
            public readonly string Name;
            public readonly long Size;
            public readonly string Key;

            public LooseFile(string name, long size, string key)
            {
                Name = name;
                Size = size;
                Key = key;
            }
        }

        /// <summary>leaf name (case-insensitive) -> the (size, key) pairs shipped under that name. Built once.</summary>
        public static Dictionary<string, List<KeyValuePair<long, string>>> BuildLooseTable(LooseFile[] files)
        {
            var t = new Dictionary<string, List<KeyValuePair<long, string>>>(StringComparer.OrdinalIgnoreCase);
            if (files == null) return t;
            foreach (LooseFile f in files)
            {
                if (string.IsNullOrEmpty(f.Name)) continue;
                List<KeyValuePair<long, string>> l;
                if (!t.TryGetValue(f.Name, out l)) t[f.Name] = l = new List<KeyValuePair<long, string>>(1);
                l.Add(new KeyValuePair<long, string>(f.Size, f.Key));
            }
            return t;
        }

        /// <summary>The unlock key of an exact (leaf name, size) match, or null when the file is not one of ours.</summary>
        public static string LooseKeyFor(string leafName, long size, Dictionary<string, List<KeyValuePair<long, string>>> table)
        {
            List<KeyValuePair<long, string>> l;
            if (table == null || string.IsNullOrEmpty(leafName) || !table.TryGetValue(leafName, out l)) return null;
            foreach (var p in l)
                if (p.Key == size) return p.Value;
            return null;
        }

        /// <summary>
        /// Pure decision: true when this loose file must be treated as absent - it is one of ours (name AND size), its key
        /// has no receipt, and the build enforces the lock (ApplyLockMode rules).
        /// </summary>
        public static bool LooseLocked(string leafName, long size, Dictionary<string, List<KeyValuePair<long, string>>> table,
                                       HashSet<string> receiptKeys, bool isTestBuild, bool enforceFileExists)
        {
            string key = LooseKeyFor(leafName, size, table);
            if (key == null) return false;
            if (receiptKeys != null && receiptKeys.Contains(key)) return false;
            return ApplyLockMode(Verdict.Locked, isTestBuild, enforceFileExists) == Verdict.Locked;
        }

        static Dictionary<string, List<KeyValuePair<long, string>>> looseTable;
        static HashSet<string> looseReceiptKeys;   // null = read on next use
        static bool looseEnforce;
        static string looseModDataDir;
        static readonly HashSet<string> looseLogged = new HashSet<string>(StringComparer.Ordinal);
        static readonly object looseSync = new object();

        /// <summary>Called by RunScanForModManager: the scan may have added a receipt, so the next loose lookup re-reads it.</summary>
        static void ResetLooseState(string modDataDir)
        {
            lock (looseSync)
            {
                looseModDataDir = modDataDir;
                looseReceiptKeys = null;
                looseLogged.Clear();
            }
        }

        /// <summary>
        /// IO: true when the file at path is one of our Non-MIT loose files whose original has no receipt (and the build
        /// enforces the lock). Only when MobileContentPath.Active; any failure -> false (the file is used, as before).
        /// </summary>
        public static bool IsLooseLocked(string path)
        {
            if (!MobileContentPath.Active || string.IsNullOrEmpty(path)) return false;
            try
            {
                var table = looseTable;
                if (table == null) looseTable = table = BuildLooseTable(KnownOursLoose);
                string leaf = Path.GetFileName(path);
                if (!table.ContainsKey(leaf)) return false;                 // the hot path: not one of our names
                var fi = new FileInfo(path);
                if (!fi.Exists) return false;
                string key = LooseKeyFor(leaf, fi.Length, table);
                if (key == null) return false;                               // same name, other size: the player's own file

                HashSet<string> keys;
                bool enforce;
                lock (looseSync)
                {
                    if (looseReceiptKeys == null)
                    {
                        string dataDir = looseModDataDir ?? Path.Combine(MobileContentPath.UserRoot, "Mods", "GameData");
                        looseReceiptKeys = ReceiptKeys(LoadReceipts(Path.Combine(dataDir, ReceiptFileName)));
                        try { looseEnforce = File.Exists(Path.Combine(dataDir, EnforceLockFileName)); }
                        catch (Exception) { looseEnforce = false; }
                    }
                    keys = looseReceiptKeys;
                    enforce = looseEnforce;
                }
                bool locked = LooseLocked(leaf, fi.Length, table, keys, IsTestBuild, enforce);
                lock (looseSync)
                {
                    if (looseLogged.Add(key + (locked ? "+L" : "+U")))
                        UnityEngine.Debug.Log(locked
                            ? string.Format("[OriginalMods] loose {0} files ignored (needs {0}), first: {1}", key, leaf)
                            : string.Format("[OriginalMods] loose {0} files used, first: {1}", key, leaf));
                }
                return locked;
            }
            catch (Exception e)
            {
                lock (looseSync)
                {
                    if (looseLogged.Add("!err"))
                        UnityEngine.Debug.Log("[OriginalMods] loose check failed: " + e.Message);
                }
                return false;
            }
        }

        /// <summary>File.Exists that treats a locked loose file as absent (for callers that test a path themselves).</summary>
        public static bool LooseFileExists(string path)
        {
            return File.Exists(path) && !IsLooseLocked(path);
        }

        /// <summary>files minus the locked loose ones; the same array when nothing is removed.</summary>
        public static string[] WithoutLockedLoose(string[] files)
        {
            if (files == null || files.Length == 0 || !MobileContentPath.Active) return files;
            List<string> kept = null;
            for (int i = 0; i < files.Length; i++)
            {
                if (IsLooseLocked(files[i]))
                {
                    if (kept == null) { kept = new List<string>(files.Length); for (int j = 0; j < i; j++) kept.Add(files[j]); }
                }
                else if (kept != null) kept.Add(files[i]);
            }
            return kept == null ? files : kept.ToArray();
        }
    }
}
